package com.yuri.music;
import android.app.*;import android.content.*;import android.webkit.CookieManager;import android.widget.*;import android.text.InputType;import android.security.keystore.*;import android.util.Base64;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
// Credentials stay in native storage and never pass through the app's JS bridge.
final class YouTubeHost{
 final Activity owner;YouTubeHost(Activity a){owner=a;}
 String session(){String cookie=CookieManager.getInstance().getCookie("https://music.youtube.com");if(cookie!=null&&cookie.contains("SAPISID="))return cookie;try{String saved=owner.getSharedPreferences("youtube-session",0).getString("secret",null);if(saved==null)return null;byte[] data=Base64.decode(saved,Base64.NO_WRAP);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(data,0,12)));return new String(cipher.doFinal(Arrays.copyOfRange(data,12,data.length)),StandardCharsets.UTF_8);}catch(Exception e){return null;}}
 SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("NocturneYouTube")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("NocturneYouTube",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}return (SecretKey)store.getKey("NocturneYouTube",null);}
 void save(String value)throws Exception{if(value.length()>65536||value.contains("\n")||value.contains("\r")||!value.contains("SAPISID="))throw new IOException("Cabeçalho Cookie inválido.");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.write(c.getIV());bytes.write(c.doFinal(value.getBytes(StandardCharsets.UTF_8)));owner.getSharedPreferences("youtube-session",0).edit().putString("secret",Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP)).apply();}
 JSONObject handle(JSONObject request)throws Exception{String op=request.getString("op");if(op.equals("yt-download"))return YouTubeDownloads.save(owner,request);if(op.equals("yt-auth"))return new JSONObject().put("connected",session()!=null).put("message",session()!=null?"Sessão encontrada. Verifique a conexão para validar a conta.":"Entre na sua conta YouTube Music.");if(op.equals("yt-login")){owner.runOnUiThread(()->owner.startActivity(new Intent(owner,YouTubeLoginActivity.class)));return new JSONObject().put("ok",true).put("message","Conclua o login na página oficial e toque em Concluir.");}if(op.equals("yt-logout")){owner.getSharedPreferences("youtube-session",0).edit().clear().apply();String existing=CookieManager.getInstance().getCookie("https://music.youtube.com");if(existing!=null)for(String part:existing.split(";")){String name=part.split("=",2)[0].trim();CookieManager.getInstance().setCookie("https://music.youtube.com",name+"=; Max-Age=0; Path=/");CookieManager.getInstance().setCookie("https://music.youtube.com",name+"=; Max-Age=0; Path=/; Domain=.youtube.com");}CookieManager.getInstance().flush();return new JSONObject().put("ok",true);}if(op.equals("yt-cancel"))return new JSONObject().put("ok",true);if(op.equals("yt-import")){owner.runOnUiThread(()->{EditText field=new EditText(owner);field.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);field.setHint("Cabeçalho Cookie da sessão YouTube Music");AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("Importar sessão · avançado").setMessage("A sessão será criptografada neste aparelho. Não compartilhe esse valor com outras pessoas.").setView(field).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,w)->{try{save(field.getText().toString().trim());Toast.makeText(owner,"Sessão protegida. Verifique a conexão.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(owner,"Sessão inválida.",Toast.LENGTH_LONG).show();}finally{field.setText("");}}).create();dialog.getWindow();dialog.setOnShowListener(d->{field.requestFocus();dialog.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);});dialog.show();});return new JSONObject().put("ok",true);}if(!op.equals("yt-http"))throw new IOException("Operação inválida.");return http(request);}
 JSONObject http(JSONObject r)throws Exception{URL u=new URL(r.getString("url"));boolean media=u.getHost().endsWith(".googlevideo.com"),api=u.getHost().equals("music.youtube.com")&&u.getPath().startsWith("/youtubei/v1/")||(u.getHost().equals("youtube.com")||u.getHost().endsWith(".youtube.com"))&&u.getPath().startsWith("/api/stats/");boolean lyrics=u.getHost().equals("lrclib.net")&&(u.getPath().equals("/api/get")||u.getPath().equals("/api/search"));if(!u.getProtocol().equals("https")||u.getPort()!=-1&&u.getPort()!=443||u.getUserInfo()!=null||!media&&!api&&!lyrics)throw new IOException("Origem não autorizada.");String method=r.optString("method","POST"),body=r.optString("body");if(body.length()>2*1024*1024||!method.equals("POST")&&!method.equals("GET")||(media||lyrics)&&!method.equals("GET"))throw new IOException("Pedido inválido.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestMethod(method);JSONObject h=r.optJSONObject("headers");boolean signed=false;if(h!=null){Iterator<String> names=h.keys();while(names.hasNext()){String name=names.next();if(name.equalsIgnoreCase("Authorization"))signed=true;for(String allowed:new String[]{"User-Agent","Accept","Origin","Referer","X-Youtube-Client-Name","X-Youtube-Client-Version","X-Goog-Visitor-Id","Range"})if(name.equalsIgnoreCase(allowed))c.setRequestProperty(name,h.optString(name));}}if(media)c.setRequestProperty("Range","bytes=0-0");if(api&&signed){String cookie=session();if(cookie==null)throw new IOException("Entre na sua conta YouTube Music.");String sapisid=null;for(String part:cookie.split(";"))if(part.trim().startsWith("SAPISID="))sapisid=part.trim().substring(8);if(sapisid==null)throw new IOException("Sessão inválida.");String time=Long.toString(System.currentTimeMillis()/1000),input=time+" "+sapisid+" https://"+u.getAuthority();StringBuilder hex=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-1").digest(input.getBytes(StandardCharsets.UTF_8)))hex.append(String.format(Locale.ROOT,"%02x",b));c.setRequestProperty("Cookie",cookie);c.setRequestProperty("Authorization","SAPISIDHASH "+time+"_"+hex);c.setRequestProperty("X-Goog-Authuser","0");}try{if(method.equals("POST")){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(media)return new JSONObject().put("status",status).put("body","");InputStream stream=status>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>16*1024*1024)throw new IOException("Resposta muito grande.");out.write(bytes,0,n);}}return new JSONObject().put("status",status).put("body",out.toString("UTF-8"));}finally{c.disconnect();}}
}
